head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[textarea > P > invalidMessage]<br/>Textarea 컴포넌트의 유효성 검증 실패 시 표시할 메시지를 설정합니다.",
    "validation" : [
        "유효성 검증 실패 시 표시할 메시지를 문자열로 설정합니다.",
        "displaymessage=true 이고 validate() 메소드의 실행결과가 실패일때 동작합니다.",
        "invalidMessageFunc 속성이 설정되면 해당 속성은 무시됩니다.",
        "설정된 메시지는 alert() 메소드로 표시됩니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};


scwin.check_validate = function (target) {
    let rtn = target.validate();

    if (rtn)
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : PASS");
    else
        wf_body_bottom.getObj("scwin").setReturnValue("validate check : FAIL");
}


// target1 (mandatory 유효성 실패 후 invalidMessage 출력)
scwin.btn_setValue1_onclick = function (e) {
    target1.setValue("");
};

scwin.btn_validate1_onclick = function (e) {
    scwin.btn_setValue1_onclick();
    scwin.check_validate(target1);
}


// target2 (maxlength 유효성 실패 후 invalidMessage 출력)
scwin.btn_setValue2_onclick = function (e) {
    target2.setValue("가나다라마바사아");
};

scwin.btn_validate2_onclick = function (e) {
    scwin.btn_setValue2_onclick();
    scwin.check_validate(target2);
}


// target3 (minlength 유효성 실패 후 invalidMessage 출력)
scwin.btn_setValue3_onclick = function (e) {
    target3.setValue("가나");
};

scwin.btn_validate3_onclick = function (e) {
    scwin.btn_setValue3_onclick();
    scwin.check_validate(target3);
}


// target4 (maxByteLength 유효성 실패 후 invalidMessage 출력)
// WebSquare 는 한글을 EUC-KR 2바이트로 계산 → '가나다라' = 8바이트 > maxByteLength=6 (FAIL)
scwin.btn_setValue4_onclick = function (e) {
    target4.setValue("가나다라");
};

scwin.btn_validate4_onclick = function (e) {
    scwin.btn_setValue4_onclick();
    scwin.check_validate(target4);
}


// target5 (minByteLength 유효성 실패 후 invalidMessage 출력)
scwin.btn_setValue5_onclick = function (e) {
    target5.setValue("가");
};

scwin.btn_validate5_onclick = function (e) {
    scwin.btn_setValue5_onclick();
    scwin.check_validate(target5);
}


// target6 (displaymessage 미설정 → invalidMessage 무시되어 alert 미출력)
scwin.btn_setValue6_onclick = function (e) {
    target6.setValue("");
};

scwin.btn_validate6_onclick = function (e) {
    scwin.btn_setValue6_onclick();
    scwin.check_validate(target6);
}


// target7 (invalidMessageFunc 설정 → invalidMessage 무시되고 fn_msg 결과 출력)
scwin.btn_setValue7_onclick = function (e) {
    target7.setValue("");
};

scwin.btn_validate7_onclick = function (e) {
    scwin.btn_setValue7_onclick();
    scwin.check_validate(target7);
}


// invalidMessageFunc 사용자 정의 함수
scwin.fn_msg = function () {
    let invalidType = this.getType();
    let invalidValue = this.getValue();
    let msg = "";

    switch (invalidType) {
        case "mandatory" :
            msg = "invalidMessageFunc 메시지 입니다.";
            break;
        case "minLength" :
            msg = "Minimum " + invalidValue + " digits are required.";
            break;
        case "maxLength" :
            msg = "Maximum " + invalidValue + " digits are required.";
            break;
        default :
            msg = "Not valid.";
            break;
    }
    return msg;
}
